      title: "\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629",
      lead: "\u062a\u0648\u0636\u062d \u0647\u0630\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0645\u0627 \u0646\u062c\u0645\u0639\u0647 \u0639\u0646\u062f \u0625\u0631\u0633\u0627\u0644\u0643 \u0644\u0644\u0637\u0644\u0628\u060c \u0648\u0643\u064a\u0641 \u0646\u0633\u062a\u062e\u062f\u0645\u0647\u060c \u0648\u0643\u064a\u0641 \u064a\u0645\u0643\u0646\u0643 \u0637\u0644\u0628 \u062a\u0635\u062d\u064a\u062d\u0647 \u0623\u0648 \u062d\u0630\u0641\u0647.",
